const std=@import("std");const s=@import("support.zig");
pub const Reservation=struct{item:[]const u8,quantity:i64};
pub fn validate(request:s.V)!void{try s.fields(request,&.{"stock","operations"});const stock=try s.array(s.get(request,"stock"),32);var ids=std.StringHashMap(void).init(std.heap.page_allocator);defer ids.deinit();for(stock)|row|{try s.fields(row,&.{"id","quantity"});const id=try s.id(s.get(row,"id"));_=try s.integer(s.get(row,"quantity"),0,1000000);if(ids.contains(id))return error.InvalidRequest;try ids.put(id,{});}const ops=try s.array(s.get(request,"operations"),128);for(ops)|op|{if(op!=.object)return error.InvalidRequest;const kind=s.get(op,"op");if(kind!=.string)return error.InvalidRequest;if(std.mem.eql(u8,kind.string,"reserve")){try s.fields(op,&.{"op","token","id","quantity"});_=try s.id(s.get(op,"token"));_=try s.id(s.get(op,"id"));_=try s.integer(s.get(op,"quantity"),1,1000000);}else if(std.mem.eql(u8,kind.string,"release")){try s.fields(op,&.{"op","token"});_=try s.id(s.get(op,"token"));}else return error.InvalidRequest;}}
